import yaml,re,json,sys
A='experiments/EXP-AUXIN-7e2e3d/amendments/'
files={'typed':'AMD-20260926-typed.yaml','narrow':'AMD-20260927-narrow.yaml','gated':'AMD-20260928-gated.yaml'}
PAT=re.compile(r'(<=|>=|(?<![-=])<(?!-)|(?<![-=])>|within|at most|at least|exceed|below|above|no more than|fewer than|more than|timeout|seconds|bits\b|digits|10\^-?\d+|2\^\d+|\b\d+(\.\d+)?\b)')
CUT=re.compile(r'(<=|>=|\s<\s|\s>\s|within|at most|at least|exceed|below|above|no more than|fewer than|more than|timeout|killed|ceiling|floor|minimum|maximum|limit|budget|window|tolerance|slack|cut-?off|threshold|bound)',re.I)
NUM=re.compile(r'(10\^-?\d+|2\^\(?[\w\-+ ]+\)?|\b\d+(\.\d+)?\b|\d+/\d+)')
def walk(x,path):
    if isinstance(x,dict):
        for k,v in x.items(): yield from walk(v,f'{path}.{k}' if path else str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x):
            lab = v.get('id') if isinstance(v,dict) and 'id' in v else (v.get('field') if isinstance(v,dict) and 'field' in v and False else None)
            yield from walk(v,f'{path}[{lab}]' if lab else f'{path}[{i}]')
    else:
        yield path,str(x)
res={}
for tag,f in files.items():
    d=yaml.safe_load(open(A+f))['amendment']
    hits=[]
    for p,s in walk(d,''):
        if p.startswith('governing_text_table') or p.startswith('supersedes_fields') : continue
        if 'sha256' in p.lower(): continue
        if CUT.search(s) and NUM.search(s):
            hits.append((p,s))
    res[tag]=hits
    print(tag,len(hits),file=sys.stderr)
json.dump(res,open('/Volumes/SSD990/tmp/rj5/scan.json','w'),indent=0)

