\\ Independent re-implementation of the C-PLANT-M and C-PLANT-P searches in GP (PARI 2.17.3).
\\ ispseudoprime(n) is PARI's BPSW; acceptance order as the recipe lists it.
default(parisize, 10^8);
B = 256; M0 = 3*2^(B-2);
S = sqrtint(M0); s0 = sqrtint(S);
d1 = nextprime(s0); d2 = nextprime(d1+1); D = d1*d2; u0 = ceil(M0/(2*D));
u = u0;
while(!(u!=d1 && u!=d2 && ispseudoprime(u) && ispseudoprime(2*D*u+1) && (2*D*u+2)%12==0 && ispseudoprime((2*D*u+2)/12)), u++);
rM = 2*D*u+1;
print("M d1=", d1, " d2=", d2, " u=", u, " r=", rM, " v=", (rM+1)/12);
d0 = sqrtnint(M0/4, 3); d = nextprime(d0); w0 = ceil(M0/(12*d));
w = w0;
while(!(w!=d && ispseudoprime(w) && ispseudoprime(12*d*w-1) && ispseudoprime((12*d*w-2)/2)), w++);
rP = 12*d*w-1;
print("P d0=", d0, " d=", d, " w=", w, " r=", rP, " q=", (rP-1)/2);
quit;

scripts.certs.py:
"""Primality certificates for every integer the C-PLANT-M / C-PLANT-P recipes require prime.
p < 2^64: Pratt tree (factorisation of p-1 by sympy.factorint, witness = smallest valid a >= 2).
p >= 2^64: ECPP chain from PARI primecert (cypari2), checked by PARI primecertisvalid AND by the
stdlib-only verifier below (independent of PARI), terminal q given a Pratt certificate."""
import json, math, sys
import sympy, cypari2
pari = cypari2.Pari(); pari.allocatemem(2*10**9, silent=True) if hasattr(pari, 'allocatemem') else None

def pratt(p, depth=0):
    if p == 2: return {'p': 2, 'leaf': True}
    fac = sympy.factorint(p - 1)
    a = 2
    while True:
        if pow(a, p-1, p) == 1 and all(pow(a, (p-1)//f, p) != 1 for f in fac): break
        a += 1
    return {'p': p, 'a': a, 'factors': {str(f): k for f, k in fac.items()},
            'sub': [pratt(f, depth+1) for f in fac]}

def check_pratt(c):
    p = c['p']
    if c.get('leaf'): return p == 2
    fac = {int(f): k for f, k in c['factors'].items()}
    prod = 1
    for f, k in fac.items(): prod *= f**k
    if prod != p - 1: return False
    a = c['a']
    if pow(a, p-1, p) != 1: return False
    if any(pow(a, (p-1)//f, p) == 1 for f in fac): return False
    return all(check_pratt(s) for s in c['sub']) and {s['p'] for s in c['sub']} == set(fac)

def ec_mul(k, P, a4, N):
    # affine; returns None for infinity; raises if a non-invertible denominator appears
    R = None; Q = P
    while k:
        if k & 1: R = ec_add(R, Q, a4, N)
        Q = ec_add(Q, Q, a4, N); k >>= 1
    return R
def inv(x, N):
    g = math.gcd(x % N, N)
    if g != 1: raise ValueError('non-invertible')
    return pow(x, -1, N)
def ec_add(P, Q, a4, N):
    if P is None: return Q
    if Q is None: return P
    x1, y1 = P; x2, y2 = Q
    if (x1 - x2) % N == 0:
        if (y1 + y2) % N == 0: return None
        l = (3*x1*x1 + a4) * inv(2*y1, N) % N
    else:
        l = (y2 - y1) * inv(x2 - x1, N) % N
    x3 = (l*l - x1 - x2) % N
    return (x3, (l*(x1 - x3) - y1) % N)

def check_ecpp(chain, p):
    Nexp = p
    for (N, t, s, a4, (x, y)) in chain:
        if N != Nexp or math.gcd(N, 6) != 1: return False, 'N/gcd'
        m = N + 1 - t
        if m % s: return False, 's|m'
        q = m // s
        b = (y*y - x*x*x - a4*x) % N
        if math.gcd(4*a4**3 + 27*b*b, N) != 1: return False, 'disc'
        try:
            if ec_mul(m, (x % N, y % N), a4, N) is not None: return False, '[m]P'
            if ec_mul(s, (x % N, y % N), a4, N) is None: return False, '[s]P'
        except ValueError: return False, 'noninv'
        c = math.isqrt(math.isqrt(N))
        while c**4 < N: c += 1
        while c > 0 and (c-1)**4 >= N: c -= 1
        if not q > (c + 1)**2: return False, 'q bound'
        Nexp = q
    return True, Nexp

def certify(p):
    if p < 2**64:
        c = pratt(p); return {'type': 'pratt', 'cert': c, 'verified_stdlib': check_pratt(c)}
    pc = pari.primecert(p)
    ok_pari = bool(pari.primecertisvalid(pc))
    chain = [(int(st[0]), int(st[1]), int(st[2]), int(st[3]), (int(st[4][0]), int(st[4][1]))) for st in pc]
    ok, term = check_ecpp(chain, p)
    tp = pratt(term)
    return {'type': 'ecpp+pratt_terminal', 'chain': [[str(v) for v in st[:4]] + [[str(st[4][0]), str(st[4][1])]] for st in chain],
            'terminal_q': str(term), 'terminal_pratt': tp,
            'verified_pari_primecertisvalid': ok_pari, 'verified_stdlib_ecpp': ok,
            'verified_stdlib_terminal_pratt': check_pratt(tp) and term < 2**64}

if __name__ == '__main__':
    I = json.load(open('/Volumes/SSD990/tmp/rj5/integers.json'))
    need = {'M.d1': I['plant_M']['d1'], 'M.d2': I['plant_M']['d2'], 'M.u': I['plant_M']['u'],
            'M.r': I['plant_M']['r'], 'M.v': I['plant_M']['v'],
            'P.d': I['plant_P']['d'], 'P.w': I['plant_P']['w'], 'P.r': I['plant_P']['r'], 'P.q': I['plant_P']['q'],
            'small.2': '2', 'small.3': '3'}
    out = {}
    for k, v in need.items():
        out[k] = {'n': v, **certify(int(v))}
        print(k, {kk: vv for kk, vv in out[k].items() if kk.startswith('verified')}, out[k]['type'], flush=True)
    json.dump(out, open('/Volumes/SSD990/tmp/rj5/certs.json', 'w'), indent=1)
